function getNext(t) {
  const next = new Array(t.length).fill(0);

  let i = 1;
  let j = 0;

  while (i < t.length) {
    if (t[i] == t[j]) {
      next[i] = j + 1;
      i++;
      j++;
    } else {
      if (j > 0) {
        j = next[j - 1];
      } else {
        i++;
      }
    }
  }

  return next;
}

